def _send_with_retries(
    api_client,
    endpoint: str,
    params: Dict[str, Any],
    retries: int,
    backoff_seconds: float,
    retry_on_statuses: List[int],
):
    """
    Send GET request with configurable retries on specific statuses, using ApiClient fixture.
    """
    attempt = 0
    while True:
        resp = api_client.get(endpoint=endpoint, params=params)
        if attempt >= retries or (retry_on_statuses and resp.status_code not in retry_on_statuses):
            return resp
        attempt += 1
        time.sleep(backoff_seconds if backoff_seconds > 0 else 0)


