    if "case" in metafunc.fixturenames:
        # Load test_data similarly to fixture but here for ids
        base_dir = Path(metafunc.definition.fspath).resolve().parent
        data_path = os.path.join(str(base_dir), "current_json.json")
        if not os.path.exists(data_path):
            metafunc.parametrize("case", [], ids=[])
            return
        with open(data_path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, list) or not data:
            metafunc.parametrize("case", [], ids=[])
            return

        def _mkid(item: Dict[str, Any]) -> str:
            q = str(item.get("q", "NA"))
            lang = str(item.get("lang", ""))
            scenario = str(item.get("scenario", ""))
            status = str(item.get("statusCode", ""))
            return f"{scenario}|q={q}|lang={lang}|status={status}"

        ids = [_mkid(d) for d in data]
        metafunc.parametrize("case", data, ids=ids)


